diff:
### acme/aidenhq fix/sbom-vanished-images (7a6b5c4d3e2f) base main
diff --git a/ops/security-sbom.sh b/ops/security-sbom.sh
index 2b3c4d5..6e7f8a9 100755
--- a/ops/security-sbom.sh
+++ b/ops/security-sbom.sh
@@ -41,9 +41,14 @@ images_to_scan() {
   for c in $(docker ps -q); do
     ref="$(docker inspect --format '{{index .Config.Labels "com.docker.compose.image"}}' "$c")"
     [ -n "$ref" ] || ref="$(docker inspect --format '{{.Image}}' "$c")"
-    echo "$ref"
+    # An image id that no longer exists (pruned after the container started) can't be scanned: pass it over.
+    if ! docker image inspect "$ref" >/dev/null 2>&1; then
+      echo "sbom: $ref no longer exists; not scanned" >&2
+      continue
+    fi
+    echo "$ref"
   done | sort -u
 }
diff --git a/ops/test/security-sbom.test.mjs b/ops/test/security-sbom.test.mjs
index 3c4d5e6..7f8a9b0 100644
--- a/ops/test/security-sbom.test.mjs
+++ b/ops/test/security-sbom.test.mjs
@@ -88,3 +88,14 @@ test("security-sbom: every running container's image is scanned", async () => {
   assert.equal(status, 0);
 });
+
+test("security-sbom: an image id that no longer exists is passed over, not a failure", async () => {
+  const { status, out, calls } = await run({}, {
+    containers: [{ id: "c1", image: "sha256:aaaa", exists: false }, { id: "c2", image: "acme/app:1.2.3", exists: true }],
+  });
+  assert.equal(status, 0);
+  assert.doesNotMatch(out, /sha256:aaaa\n/);
+  assert.match(out, /acme\/app:1\.2\.3/);
+  assert.ok(!calls.some((c) => c.includes("save sha256:aaaa")));
+});
